            const scar = SafeGetValue(characterData, '心之所向.心中傷疤', 0);
            const scarStages = [
                { range: [401, 500], name: '往事如魘' },
                { range: [301, 400], name: '患得患失' },
                { range: [201, 300], name: '尋求慰藉' },
                { range: [101, 200], name: '逐漸釋懷' },
                { range: [0, 100], name: '雨過天晴' }
            ];
            const currentScarStage = scarStages.find(stage => scar >= stage.range[0] && scar <= stage.range[1]);
            document.getElementById('heart-scar-value').innerText = currentScarStage ? currentScarStage.name : '未知階段';
            updateProgressBar('heart-scar-bar', null, scar, 0, 500);

            document.getElementById('heat-status').innerText = SafeGetValue(characterData, '發情期.狀態');
            document.getElementById('heat-next').innerText = SafeGetValue(characterData, '發情期.下次發情時間');
            document.getElementById('heat-duration').innerText = SafeGetValue(characterData, '發情期.發情持續時間');
            document.getElementById('heat-scent').innerText = SafeGetValue(characterData, '發情期.散發出的味道');
            document.getElementById('heat-desire').innerText = SafeGetValue(characterData, '發情期.情慾需求');
            updateProgressBar('heat-progress-bar', 'heat-progress-value', SafeGetValue(characterData, '發情期.進度', 0), 0, 500);

            switchTab('kozaki', document.querySelector('.tab-button[onclick*="kozaki"]'));
        } catch (error) {
            console.error('Error loading status bar:', error);
        }
    }

    document.addEventListener('DOMContentLoaded', initDisplay);
</script>
